using CustomCodeFramework.Messaging.DependencyInjection;using CustomCodeFramework.Messaging.Outbox.DependencyInjection;using CustomCodeFramework.Mongo.DependencyInjection;using CustomCodeFramework.Redis.DependencyInjection;using CustomCodeFramework.Redis.Streams.DependencyInjection;using CustomCodeFramework.Workers.DependencyInjection;using Dhole.Content.Application.Abstractions.Cache;using Dhole.Content.Application.Abstractions.Mongo;using Dhole.Content.Infrastructure.Cache;using Dhole.Content.Infrastructure.Mongo;using Dhole.Content.Worker.Outbox;using Dhole.Content.Worker.Streams;using Dhole.Content.Worker.Workers;namespace Dhole.Content.Worker.DependencyInjection;
public static class WorkerServiceCollectionExtensions{public static IServiceCollection AddContentWorker(this IServiceCollection services,IConfiguration configuration){services.AddCustomCodeRedis(configuration);services.AddCustomCodeMongo(configuration);services.AddCustomCodeRedisStreams(configuration);services.AddScoped<IContentCacheService,ContentCacheService>();services.AddScoped<IContentChangeSnapshotWriter,ContentChangeSnapshotWriter>();services.AddCustomCodeMessaging(configuration);services.AddCustomCodeMessagingOutbox(configuration);services.AddCustomCodeOutboxProcessor<OutboxProcessor>();services.AddCustomCodeInboxProcessor<InboxProcessor>();services.AddCustomCodeMessagingOutboxHostedServices();services.AddCustomCodeRedisStreamConsumerBackgroundService();services.AddCustomCodeRedisStreamHandler<ContentItemCreatedStreamHandler>();services.AddCustomCodeRedisStreamHandler<ContentItemUpdatedStreamHandler>();services.AddCustomCodeRedisStreamHandler<ContentItemReviewRequestedStreamHandler>();services.AddCustomCodeRedisStreamHandler<ContentItemPublishedStreamHandler>();services.AddCustomCodeRedisStreamHandler<ContentItemScheduledStreamHandler>();services.AddCustomCodeRedisStreamHandler<ContentItemUnpublishedStreamHandler>();services.AddCustomCodeRedisStreamHandler<ContentItemArchivedStreamHandler>();services.AddCustomCodeRedisStreamHandler<ContentItemDeletedStreamHandler>();services.AddCustomCodeRedisStreamHandler<ContentItemRevisionRestoredStreamHandler>();services.AddCustomCodeRedisStreamHandler<TaxonomyCreatedStreamHandler>();services.AddCustomCodeRedisStreamHandler<TaxonomyUpdatedStreamHandler>();services.AddCustomCodeRedisStreamHandler<TaxonomyDeletedStreamHandler>();services.AddCustomCodeRedisStreamHandler<MediaCreatedStreamHandler>();services.AddCustomCodeRedisStreamHandler<MediaDeletedStreamHandler>();services.AddCustomCodeRedisStreamHandler<MenuChangedStreamHandler>();services.AddCustomCodeRedisStreamHandler<SettingChangedStreamHandler>();services.AddCustomCodeWorkers(configuration);services.AddCustomCodePeriodicWorker<ScheduledContentPublishingWorker>();services.AddCustomCodePeriodicWorker<ContentCacheWarmupWorker>();return services;}}
